//! Per-block sounds: vanilla's `SoundType` for every block.
//!
//! `azalea-block` does not expose sound types, so `block_sounds.json` is
//! generated by `just soundgen`, which asks each version's vanilla for every
//! block's `getSoundType()` (`tools/stategen/SoundDump.java`): each block's
//! newest sound type, and the older versions' types where they differ.
//!
//! TODO: `DecoratedPotBlock` cracks to `DECORATED_POT_CRACKED` by state; the
//! table holds each block's default state only.

use std::collections::{HashMap, HashSet};
use std::sync::{LazyLock, Mutex};

use serde::Deserialize;

use super::BlockStateTable;

/// A block's vanilla `SoundType`: the raw volume and pitch (the caller applies
/// the play-time scaling) and its `sounds.json` events. An empty event marks
/// an action that is intentionally silent for the block.
#[derive(Deserialize)]
pub struct BlockSounds {
    pub volume: f32,
    pub pitch: f32,
    pub break_event: String,
    pub step_event: String,
    _place_event: serde::de::IgnoredAny,
    pub hit_event: String,
    _fall_event: serde::de::IgnoredAny,
}

/// The distinct sound types, each block id (no namespace)'s index into them,
/// and per version the blocks whose type differs there.
#[derive(Deserialize)]
pub(super) struct SoundTable {
    types: Vec<BlockSounds>,
    pub(super) blocks: HashMap<String, usize>,
    versions: HashMap<String, HashMap<String, usize>>,
}

pub(super) static BLOCK_SOUNDS: LazyLock<SoundTable> = LazyLock::new(|| {
    serde_json::from_str(include_str!("block_sounds.json"))
        .expect("embedded block_sounds.json must be valid")
});

/// The vanilla `SoundType` for a name resolved from `table`'s block data, as
/// `table`'s version has it. Unknown ids fall back to the vanilla
/// `SoundType.STONE` default.
pub(crate) fn block_sounds_for_id(table: BlockStateTable, id: &str) -> &'static BlockSounds {
    let key = id.strip_prefix("minecraft:").unwrap_or(id);
    let index = BLOCK_SOUNDS
        .versions
        .get(table.version())
        .and_then(|blocks| blocks.get(key))
        .or_else(|| BLOCK_SOUNDS.blocks.get(key))
        .copied()
        .unwrap_or_else(|| {
            // Coverage is test-enforced, so a miss means table drift. Once per
            // key: this path runs every hit/break tick.
            static WARNED: LazyLock<Mutex<HashSet<String>>> = LazyLock::new(Default::default);
            if WARNED.lock().unwrap().insert(key.to_string()) {
                tracing::warn!("no sound entry for block '{key}', using stone");
            }
            BLOCK_SOUNDS.blocks["stone"]
        });
    &BLOCK_SOUNDS.types[index]
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn embedded_table_matches_vanilla() {
        assert!(
            BLOCK_SOUNDS.blocks.len() > 1000,
            "expected the full vanilla block set, got {}",
            BLOCK_SOUNDS.blocks.len()
        );

        let native = BlockStateTable::native();
        let stone = block_sounds_for_id(native, "stone");
        assert_eq!(stone.hit_event, "block.stone.hit");
        assert_eq!(stone.step_event, "block.stone.step");
        // `BlockSetType.OAK`, and `SoundType.GRAVEL` on dirt.
        assert_eq!(
            block_sounds_for_id(native, "oak_door").step_event,
            "block.wood.step"
        );
        assert_eq!(
            block_sounds_for_id(native, "dirt").step_event,
            "block.gravel.step"
        );
        // METAL carries a non-default pitch.
        let gold = block_sounds_for_id(native, "minecraft:gold_block");
        assert_eq!((gold.volume, gold.pitch), (1.0, 1.5));
        // Silent hit and step, but the break sound is still present.
        let flower = block_sounds_for_id(native, "cactus_flower");
        assert_eq!(flower.hit_event, "");
        assert_eq!(flower.step_event, "");
        assert_eq!(flower.break_event, "block.cactus_flower.break");
    }

    #[test]
    fn every_version_override_names_an_embedded_table() {
        for version in BLOCK_SOUNDS.versions.keys() {
            assert!(
                crate::world::block::BLOCK_DATA
                    .iter()
                    .any(|d| d.version == version),
                "{version}"
            );
        }
    }

    #[test]
    fn older_versions_keep_their_own_sound_types() {
        // Iron blocks took `SoundType.IRON` in 1.21.5; 1.20.1's 763 still
        // had them on `METAL`.
        let iron = |protocol| {
            &block_sounds_for_id(BlockStateTable::for_protocol(protocol), "iron_block").step_event
        };
        assert_eq!(iron(763), "block.metal.step");
        assert_eq!(
            iron(pomme_protocol::version::NATIVE.protocol),
            "block.iron.step"
        );
    }
}
